for name,color,poly in zones:
 x,y=poly.split()[0].split(',');svg+=f'<polygon points="{poly}" fill="{color}" fill-opacity=".13" stroke="{color}" stroke-width="3" stroke-dasharray="10 7"/><text class="zone-label" x="{int(x)+12}" y="{int(y)+24}">{html.escape(name)}</text>'
