for id,name,x,y,desc in towns:
 ly=y-32 if id not in ['I','III','V','VIII'] else y+41
 svg+=f'<g class="poi town" role="button" tabindex="0" data-kind="town" data-id="{id}" aria-label="{html.escape(name)}"><circle cx="{x}" cy="{y}" r="12"/><text class="code" x="{x}" y="{y+5}">{id}</text><text class="label" x="{x}" y="{ly}" text-anchor="middle">{html.escape(name)}</text><title>{html.escape(desc)}</title></g>'
svg+='</g><g class="layer faction" data-layer="faction">'
